// A motif keeps its response in each of the twenty illustrated settings.
// A quiet sticker can still light up, move or show a little speech bubble.
function reaction(motion, caption, sound = null, plain = caption.replace(/\p{M}/gu, '')) {
  return Object.freeze({ motion, sound, caption, plain });
}

